// hasAnyLearning reports whether at least one learning subsection is populated.
func hasAnyLearning(l checkpoint.LearningsSummary) bool {
	return len(l.Repo) > 0 || len(l.Code) > 0 || len(l.Workflow) > 0
}

// formatCodeLearning renders a CodeLearning entry as a single markdown
// bullet line. Path is wrapped in inline-code backticks so glamour
// styles it; line ranges become "path:line-endLine", a single line
// becomes "path:line", and a path-only entry becomes just "path".
func formatCodeLearning(c checkpoint.CodeLearning) string {
	path := escapeSummaryText(c.Path)
	finding := escapeSummaryText(c.Finding)
	switch {
	case c.Line > 0 && c.EndLine > 0:
		return fmt.Sprintf("`%s:%d-%d` — %s", path, c.Line, c.EndLine, finding)
	case c.Line > 0:
		return fmt.Sprintf("`%s:%d` — %s", path, c.Line, finding)
	default:
		return fmt.Sprintf("`%s` — %s", path, finding)
	}
}

// escapeSummaryText sanitizes a user-visible string for safe inclusion
// in markdown. Trims leading/trailing whitespace and replaces literal
// backticks with U+2018 (left single quotation mark) so AI-generated
// content cannot break out of inline-code spans.
func escapeSummaryText(s string) string {
	return strings.ReplaceAll(strings.TrimSpace(s), "`", "‘")
}
