// formatCheckpointHeader builds the metadata block that sits above the
// summary body. When styles.colorEnabled is true, the result contains
// lipgloss ANSI escapes; when false, the same shape is emitted as plain
// text. Layout: "● Checkpoint <id>" headline followed by indented
// "label  value" rows for session/created/author/tokens/commits. Author
// is conditional on author.Name != ""; tokens follows the existing
// fallback (prefer meta.TokenUsage, fall back to summary.TokenUsage,
// omit when both nil); commits is conditional on len(commits) > 0 and
// expands to a multi-line block when len(commits) > 1.
func formatCheckpointHeader(
	summary *checkpoint.CheckpointSummary,
	meta checkpoint.CommittedMetadata,
	cpID id.CheckpointID,
	commits []associatedCommit,
	author checkpoint.Author,
	styles statusStyles,
) string {
	var sb strings.Builder

	headline := "● Checkpoint " + cpID.String()
	if styles.colorEnabled {
		bullet := styles.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), "●")
		key := styles.render(styles.bold, "Checkpoint")
		val := styles.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), cpID.String())
		headline = bullet + " " + key + " " + val
	}
	sb.WriteString(headline)
	sb.WriteString("\n")

	writeRow := func(label, value string) {
		// 10-char label column, two-space gutter, value.
		paddedLabel := fmt.Sprintf("%-10s", label)
		if styles.colorEnabled {
			paddedLabel = styles.render(styles.dim, paddedLabel)
		}
		fmt.Fprintf(&sb, "  %s%s\n", paddedLabel, value)
	}

	writeRow("session", meta.SessionID)
	writeRow("created", meta.CreatedAt.Format("2006-01-02 15:04:05"))
	if author.Name != "" {
		authorVal := fmt.Sprintf("%s <%s>", author.Name, author.Email)
		writeRow("author", authorVal)
	}

	tokenUsage := meta.TokenUsage
	if tokenUsage == nil && summary != nil {
		tokenUsage = summary.TokenUsage
	}

