// buildFilesMarkdown renders the touched-files list as a "## Files"
// markdown block, suitable to append to the summary markdown when
// --verbose or --full is set. Used only on the meta.Summary != nil
// path; the no-summary path keeps the legacy "Files: (N)" plain shape.
func buildFilesMarkdown(files []string) string {
	if len(files) == 0 {
		return "\n## Files\n\n*(none)*\n"
	}
	var sb strings.Builder
	sb.WriteString("\n## Files\n\n")
	for _, f := range files {
		fmt.Fprintf(&sb, "- %s\n", f)
	}
	return sb.String()
}
```

