```go
// buildPagerCmd constructs the pager subprocess. Resolves the pager
// from $PAGER (default "less" on Unix, "more" on Windows) and injects
// LESS=-R when the user has not customized PAGER or LESS — so glamour
// ANSI passes through less unmangled. Returns the configured *exec.Cmd
// and the resolved pager binary name. The caller is responsible for
// setting Stdin / Stdout / Stderr and calling Run.
//
// Extracted from outputWithPager so the env-gate logic is directly
// testable without needing to fake a *os.File TTY.
func buildPagerCmd(ctx context.Context) (*exec.Cmd, string) {
	pager := pagerLookupEnv("PAGER")
	if pager == "" {
		if runtime.GOOS == "windows" {
			pager = "more"
		} else {
			pager = "less"
		}
	}

	cmd := exec.CommandContext(ctx, pager)
	if pager == "less" && pagerLookupEnv("PAGER") == "" && pagerLookupEnv("LESS") == "" {
		// -R is a no-op on plain content, so it is safe to set
		// unconditionally on this gated branch.
		cmd.Env = append(os.Environ(), "LESS=-R")
	}
	return cmd, pager
}
```

